contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        address originalOwner = c.owner();
        // Owner (this contract) sets owner to a scratch address different from newOwner
        address scratch = address(uint160(uint256(keccak256(abi.encode(newOwner, originalOwner)))) );
        if (scratch == newOwner) { scratch = address(uint160(uint256(keccak256(abi.encode(scratch))))); }
        c.setOwner(scratch);
        // Now a non-owner calls setOwner: since every external call to c comes from this
        // contract, use the fact that setOwner requires msg.sender == owner; the owner is
        // 'scratch', not this contract, so the call must revert.
        bool reverted;
        try c.setOwner(newOwner) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.owner() == scratch);
        // restore: transfer ownership back through scratch is impossible from here,
        // but the rule above is the checked property.
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(this));
        // Deployer of c is this contract, so we are the owner; transfer ownership away.
        bool firstOk;
        try c.setOwner(newOwner) { firstOk = true; }
        catch { firstOk = false; }
        // Now this contract is a non-owner; another setOwner must revert.
        bool reverted;
        try c.setOwner(address(this)) { reverted = false; }
        catch { reverted = true; }
        assert(firstOk && reverted && c.owner() == newOwner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a) public payable {
        address ownerBefore = c.owner();
        bool reverted;
        bool ret;
        try c.setOwner(a) returns (bool r) { reverted = false; ret = r; }
        catch { reverted = true; ret = false; }
        address ownerAfter = c.owner();
        assert((!reverted && ret && ownerAfter == a) || (reverted && ownerAfter == ownerBefore));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a) public payable {
        require(c.owner() != address(this));
        bool reverted;
        address before = c.owner();
        try c.setOwner(a) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == before);
    }
    receive() external payable {}
}

